// Typed access to manifest.json, which is generated by tools/publish-photos.
// Never edit manifest.json by hand — edit series.yaml in ~/Photography/Portfolio and re-run publish.
import raw from "../data/manifest.json";

export type Format = "avif" | "jpg";

export interface Photo {
  id: string;
  /** Object key prefix; files live at `${imageBase}/${key}-${width}.${format}`. */
  key: string;
  w: number;
  h: number;
  widths: number[];
  formats: Format[];
  color: string;
  alt: string;
  caption?: string;
  date?: string;
}

export interface Series {
  slug: string;
  title: string;
  date: string; // YYYY-MM-DD
  year: number;
  description?: string;
  cover: string; // Photo id
  images: Photo[];
}

export interface Manifest {
  version: 1;
  imageBase: string;
  generatedAt: string | null;
  series: Series[];
}

export const manifest = raw as unknown as Manifest;

export const series: Series[] = [...manifest.series].sort((a, b) => b.date.localeCompare(a.date));

export function src(p: Photo, width: number, format: Format): string {
  return `${manifest.imageBase}/${p.key}-${width}.${format}`;
}

export function srcset(p: Photo, format: Format): string {
  return p.widths.map((w) => `${src(p, w, format)} ${w}w`).join(", ");
}

export function coverOf(s: Series): Photo {
  return s.images.find((i) => i.id === s.cover) ?? s.images[0]!;
}

export function formatDate(iso: string): string {
  const d = new Date(`${iso}T00:00:00Z`);
  return d.toLocaleDateString("en-GB", { month: "long", year: "numeric", timeZone: "UTC" });
}
